"""Random, unique robot names of the form AA123 (two letters, three digits)."""

import random
import string


class Robot:
    _used_names = set()

    def __init__(self):
        self.name = None

    @property
    def name(self):
        if self._name is None:
            self._name = self._generate_name()
        return self._name

    @name.setter
    def name(self, value):
        self._name = value

    def reset(self):
        """Wipe the name; the next access assigns a fresh unique one."""
        self.name = None

    def _generate_name(self):
        while True:
            name = (
                random.choice(string.ascii_uppercase)
                + random.choice(string.ascii_uppercase)
                + random.choice(string.digits)
                + random.choice(string.digits)
                + random.choice(string.digits)
            )
            if name not in self._used_names:
                self._used_names.add(name)
                return name
```

**How it satisfies the spec:**
- **No name at the factory**: a fresh `Robot` has no name; the first access to `.name` ("turning on") lazily generates one.
- **Format**: two uppercase letters + three digits, built from `random.choice` (e.g. `LY862`, `EX210`) — genuinely random, no predictable sequence.
- **Persistence**: once generated, `.name` keeps returning the same value.
- **Reset**: `reset()` wipes the name; the next access assigns a new random name.
- **Uniqueness**: a class-level `_used_names` set is the global registry — every generated name is checked against it and retried on collision, and old names are never reissued, so every existing robot's name is unique (verified with 10,000 robots, zero collisions).

